#include <cstdint>
#include <iostream>
#include <vector>

int main()
{
    int W{}, T{};
    if (!(std::cin >> W >> T)) return 0;

    std::vector<int> taps;
    for (int i = 0; i < T; ++i)
    {
        int t{};
        std::cin >> t;
        taps.push_back(t);
    }

    std::uint32_t seed{};
    int cycles{};
    std::cin >> seed >> cycles;

    const std::uint32_t mask{ (std::uint32_t{ 1 } << W) - 1 };
    std::uint32_t reg{ seed & mask };
    const std::uint32_t start{ reg };

    std::vector<std::uint32_t> values;
    std::vector<unsigned> bits;
    long long period{ -1 };

    for (int c = 1; c <= cycles; ++c)
    {
        /* Everything here reads the OLD register, then one assignment commits. */
        unsigned fb{ 0 };
        for (int t : taps) fb ^= (reg >> t) & 1u;
        unsigned outBit{ (reg >> (W - 1)) & 1u };

        reg = ((reg << 1) | fb) & mask;

        values.push_back(reg);
        bits.push_back(outBit);
        if (period < 0 && reg == start) period = c;
    }

    std::cout << "values";
    for (std::uint32_t v : values) std::cout << ' ' << v;
    std::cout << "\n";

    std::cout << "bits";
    for (unsigned b : bits) std::cout << ' ' << b;
    std::cout << "\n";

    if (period < 0) std::cout << "period none\n";
    else            std::cout << "period " << period << "\n";

    return 0;
}
